      "attack_scenario": "Legion admin (or a compromised/misconfigured deployment) initializes a capital raise with combined fee BPS > 10000 (e.g., legionFee=6000, referrerFee=5000); all subsequent calls to `withdrawCapital` revert due to arithmetic underflow, permanently locking raised investor funds in the contract.",
      "checklist_id": "PROP-legion-backe-inv-027"
    },
    "text": "Fee basis points must be valid (0..10000) and sum must not exceed 10000.",
    "assertion": "legionFeeBps + referrerFeeBps <= 10000 && each <= 10000",
    "covers": "SG-001",
    "severity": "HIGH",
    "type": "invariant"
  }
}

